import{_ as t,o as a,c as i,a5 as n}from"./chunks/framework.CsGesDJn.js";const f=JSON.parse('{"title":"Task five-state inline editing — DA-978 / FR 3.6.1, 3.6.2","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/task-five-state-inline-edit/spec.md","filePath":"feature/content-task-workflow/task-five-state-inline-edit/spec.md"}'),s={name:"feature/content-task-workflow/task-five-state-inline-edit/spec.md"};function r(o,e,l,d,c,p){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="task-five-state-inline-editing-—-da-978-fr-3-6-1-3-6-2" tabindex="-1">Task five-state inline editing — DA-978 / FR 3.6.1, 3.6.2 <a class="header-anchor" href="#task-five-state-inline-editing-—-da-978-fr-3-6-1-3-6-2" aria-label="Permalink to &quot;Task five-state inline editing — DA-978 / FR 3.6.1, 3.6.2&quot;">​</a></h1><p>&gt; <strong>Current amendment 2026-10-18:</strong> no QC/plannedPublishAt in new workflow (see <a href="./../task-structure-simplification/spec.html">Task structure</a>); approval uses Manager → optional Client under <a href="./../3-6-9-approval-sequence-creator-manager-client/spec.html">FR 3.6.9 v3</a>. Historical QC/ownership/snapshot clauses below are not the current approval contract. This amendment is documentation, not completed Approval implementation.</p><h2 id="ba-confirmed-2026-10-15" tabindex="-1">BA confirmed 2026-10-15 <a class="header-anchor" href="#ba-confirmed-2026-10-15" aria-label="Permalink to &quot;BA confirmed 2026-10-15&quot;">​</a></h2><p>Five business states TODO / IN_PROGRESS / IN_REVIEW / CANCELLED / FINISHED. New Tasks, requirements preparation and assignment stay TODO; no DETAIL_IDENTIFIED/ASSIGNED step. Before assignment: nonblank description and valid deadline, active Creator, optional distinct active QC. Only assigned Creator explicitly starts. After first start Manager cannot edit requirements/deadline/reassign, including after rejection. Client reads every Workspace Task, never edits/assigns/starts. Approval remains QC if configured -&gt; Manager -&gt; Client if required; final approval finishes, rejection returns IN_PROGRESS, resubmit restarts QC if configured. User confirms Approval belongs to teammate: this slice ONLY state/integration contract; no submit/approve/reject endpoints or editor changes. List actions ONLY Manager assignment/deadline and assigned Creator start. Detail autosaves on blur/selection, NOT every keystroke or multi-user realtime. TODO draft may be incomplete; assignment/start require description + valid deadline. Assigned TODO cannot clear required information. Retain failed drafts, show saving/saved/error, do not silently retry stale revisions.</p><h2 id="layout-and-ui" tabindex="-1">Layout and UI <a class="header-anchor" href="#layout-and-ui" aria-label="Permalink to &quot;Layout and UI&quot;">​</a></h2><p>Tasks-only fixed workspace layout; Navbar/title/tabs/filters/pagination fixed, list and detail independently scroll. Nonmodal desktop panel, Sheet mobile. Five status groups, localized columns, no unsupported Priority UI. Keyboard/focus and semantic light/dark tokens; parallel tasks.inline/tasks.status/tasks.panel keys in src/i18n/locales/{vi,en}/tasks.json.</p><h2 id="compatibility-contract" tabindex="-1">Compatibility / contract <a class="header-anchor" href="#compatibility-contract" aria-label="Permalink to &quot;Compatibility / contract&quot;">​</a></h2><p>Legacy values read/filter as TODO (BACKLOG/DETAIL_IDENTIFIED/ASSIGNED), IN_REVIEW (QC_REVIEW/MANAGER_REVIEW/CLIENT_REVIEW; derive reviewStep), FINISHED (COMPLETED). New writers use canonical states. Temporarily retain legacy schema enums for old data/writers; no document conversion or invented first-start evidence. Migration preflight/explicit operator approval before Atlas APPLY; init fresh-only. Keep detail/assign/start APIs, add targeted PATCH /tasks/{taskId}/field {field,value,expectedRevision}, allowlist description/dueDate/plannedPublishAt/inputReferences. Preserve untouched data, CAS, memberships, dates, Campaign lock and cancellation audit. Workflow exposes reviewStep for integration, no arbitrary status mutation.</p>',8)])])}const m=t(s,[["render",r]]);export{f as __pageData,m as default};
